text:
#dash-root { --dash-gutter: clamp(18px, 4vw, 64px); color-scheme: light; color: #20211f; background: #fafaf8; font-family: "Segoe UI", "Microsoft YaHei", Arial, sans-serif; }
#dash-root .sc-dashboard { max-width: 1500px; min-width: 0; margin-inline: auto; padding-block: 22px 48px; color: #20211f; background: #fafaf8; }
#dash-root .sc-dashboard * { box-sizing: border-box; }
#dash-root .sc-header { margin-bottom: 30px; }
#dash-root .sc-title { margin: 0 0 6px; color: #191b19; font: 400 clamp(27px, 2.6vw, 37px)/1.4 "Noto Serif SC", "Source Han Serif SC", "Songti SC", SimSun, Georgia, serif; letter-spacing: .01em; }
#dash-root .sc-title-note { white-space: nowrap; }
#dash-root .sc-intro { min-height: 26px; margin: 0; color: #62655f; font-size: 16px; line-height: 1.7; }
#dash-root .sc-intro strong { color: #242622; font-weight: 600; }
#dash-root .sc-disclaimer { margin: 7px 0 0; color: #68725e; font-size: 12px; letter-spacing: .02em; }
#dash-root .sc-filters { display: flex; align-items: flex-end; flex-wrap: wrap; gap: 12px 18px; margin-bottom: 28px; padding-bottom: 20px; border-bottom: 1px solid #e5e6df; }
#dash-root .sc-field { display: flex; flex-direction: column; gap: 6px; color: #64685f; font-size: 12px; }
#dash-root .sc-field input, #dash-root .sc-field select { max-width: 100%; min-height: 36px; border: 1px solid #d9dcd4; border-radius: 5px; padding: 6px 10px; background: #ffffff; color: #252923; font: 14px/1.3 "Segoe UI", "Microsoft YaHei", Arial, sans-serif; }
#dash-root .sc-field input { min-width: 156px; }
#dash-root .sc-field select { min-width: 142px; }
#dash-root .sc-reset { min-height: 36px; padding: 6px 1px; border: 0; border-bottom: 1px solid transparent; background: transparent; color: #526153; font: 13px/1.4 "Segoe UI", "Microsoft YaHei", Arial, sans-serif; cursor: pointer; }
#dash-root .sc-reset:hover { color: #202b20; border-bottom-color: #a2ad9e; }
#dash-root .sc-field input:focus-visible, #dash-root .sc-field select:focus-visible, #dash-root .sc-reset:focus-visible, #dash-root .sc-table button:focus-visible, #dash-root .sc-chart-interactive:focus-visible { outline: 2px solid #2a78d6; outline-offset: 3px; }
#dash-root .sc-section { margin-bottom: 36px; min-width: 0; }
#dash-root .sc-section-title { margin: 0 0 6px; color: #272b25; font-size: 17px; line-height: 1.5; font-weight: 600; }
#dash-root .sc-section-note { min-height: 20px; margin: 0 0 18px; color: #68725e; font-size: 13px; line-height: 1.6; }
#dash-root .sc-kpis { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 16px; }
#dash-root .sc-kpi { min-width: 0; min-height: 178px; padding: 20px 19px 18px; border: 1px solid #e0e3db; border-radius: 8px; color: #20211f; background: #ffffff; }
#dash-root .sc-kpi h3 { margin: 0 0 18px; color: #6b7461; font-size: 13px; line-height: 1.4; font-weight: 400; }
#dash-root .sc-value { margin: 0 0 9px; color: #181b17; font-size: clamp(29px, 3vw, 42px); line-height: 1.08; font-weight: 550; letter-spacing: -.025em; white-space: nowrap; font-variant-numeric: proportional-nums; }
#dash-root .sc-change { display: flex; align-items: baseline; flex-wrap: wrap; gap: 5px; min-height: 20px; margin: 0 0 10px; color: #575c52; font-size: 13px; line-height: 1.5; }
#dash-root .sc-change-note { color: #68725e; font-size: 11px; }
#dash-root .sc-positive { color: #347641; }
#dash-root .sc-negative { color: #a04645; }
#dash-root .sc-definition { margin: 0; color: #68725e; font-size: 12px; line-height: 1.65; }
#dash-root .sc-chart-card { min-width: 0; margin-top: 17px; border: 1px solid #e0e3db; border-radius: 8px; padding: 19px 20px 12px; color: #20211f; background: #ffffff; }
#dash-root .sc-chart-card h3 { margin: 0 0 8px; color: #252922; font-size: 16px; line-height: 1.5; font-weight: 600; }
#dash-root .sc-card-note { margin: 0 0 15px; color: #68725e; font-size: 12px; line-height: 1.6; }
#dash-root .sc-chart-header { display: flex; align-items: flex-start; justify-content: space-between; flex-wrap: wrap; gap: 6px 20px; }
#dash-root .sc-legend { display: flex; flex-wrap: wrap; gap: 14px; padding-top: 4px; color: #62695d; font-size: 12px; white-space: nowrap; }
#dash-root .sc-legend span { display: inline-flex; align-items: center; gap: 6px; }
#dash-root .sc-legend-bar { width: 9px; height: 12px; border-radius: 1px; background: #bfc3b7; }
#dash-root .sc-legend-line { width: 17px; height: 0; border-top: 2px solid #2a78d6; }
#dash-root .sc-chart { min-width: 0; width: 100%; position: relative; }
#dash-root .sc-chart-main { min-height: 300px; }
#dash-root .sc-chart-small { min-height: 210px; }
#dash-root .sc-chart-interactive { position: relative; width: 100%; border-radius: 3px; }
#dash-root .sc-chart svg { display: block; width: 100%; max-width: 100%; overflow: visible; }
#dash-root .sc-chart svg text { fill: #68725e; font-family: "Segoe UI", "Microsoft YaHei", Arial, sans-serif; font-size: 11px; font-variant-numeric: tabular-nums; }
#dash-root .sc-tooltip { position: absolute; z-index: 4; max-width: calc(100% - 16px); width: 202px; padding: 11px 12px; border: 1px solid #d9ded1; border-radius: 6px; background: #ffffff; color: #252b21; box-shadow: 0 4px 15px #1e2b1b12; pointer-events: none; font-size: 12px; line-height: 1.7; }
#dash-root .sc-tooltip-date { color: #68725e; margin-bottom: 5px; }
#dash-root .sc-tooltip-row { display: flex; justify-content: space-between; gap: 12px; }
#dash-root .sc-tooltip-row strong { color: #20271a; font-weight: 600; font-variant-numeric: tabular-nums; }
#dash-root .sc-chart-range { margin: 3px 0 0; color: #68725e; font-size: 11px; line-height: 1.5; text-align: right; }
#dash-root .sc-related-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 20px; }
#dash-root .sc-related-grid .sc-chart-card { margin-top: 10px; }
#dash-root .sc-empty { display: flex; align-items: center; justify-content: center; min-height: 210px; color: #68725e; font-size: 13px; text-align: center; padding: 24px; }
#dash-root .sc-table-heading { display: flex; align-items: flex-end; justify-content: space-between; gap: 16px; }
#dash-root .sc-table-count { margin: 0 0 18px; color: #68725e; font-size: 12px; white-space: nowrap; }
#dash-root .sc-table-scroll { max-width: 100%; max-height: 348px; overflow: auto; border: 1px solid #e0e3db; border-radius: 8px; background: #ffffff; }
#dash-root .sc-table { border-collapse: collapse; width: 100%; color: #3d4436; font-size: 12px; line-height: 1.5; font-variant-numeric: tabular-nums; }
#dash-root .sc-table th { position: sticky; top: 0; padding: 12px 15px; border-bottom: 1px solid #dfe4d8; color: #68725e; background: #f6f8f2; font-weight: 500; text-align: right; white-space: nowrap; }
#dash-root .sc-table td { padding: 10px 15px; border-bottom: 1px solid #edf0e8; color: #444c3b; text-align: right; white-space: nowrap; }
#dash-root .sc-table th:first-child, #dash-root .sc-table td:first-child { text-align: left; }
#dash-root .sc-table button { padding: 0; border: 0; background: transparent; color: inherit; font: inherit; cursor: pointer; }
#dash-root .sc-table tr:last-child td { border-bottom: 0; }
#dash-root .sc-table tr:hover td { background: #f6f8f2; }
#dash-root .sc-footer { display: flex; flex-direction: column; gap: 5px; padding-top: 1px; color: #68725e; font-size: 11px; line-height: 1.7; }
#dash-root .sc-footer p { margin: 0; color: #68725e; }
@media (max-width: 1100px) { #dash-root .sc-kpis { grid-template-columns: repeat(3, minmax(0, 1fr)); } #dash-root .sc-kpi { min-height: 165px; } }
@media (max-width: 720px) { #dash-root .sc-dashboard { padding-block: 16px 32px; } #dash-root .sc-header { margin-bottom: 23px; } #dash-root .sc-intro { font-size: 14px; } #dash-root .sc-related-grid { grid-template-columns: minmax(0, 1fr); gap: 10px; } #dash-root .sc-kpis { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; } #dash-root .sc-kpi { padding: 17px 14px; } #dash-root .sc-value { font-size: 31px; } #dash-root .sc-chart-card { padding: 16px 12px 10px; } #dash-root .sc-chart-main { min-height: 250px; } #dash-root .sc-table th, #dash-root .sc-table td { padding: 10px; } #dash-root .sc-section { margin-bottom: 28px; } }
@media (max-width: 390px) { #dash-root .sc-field { flex: 1 1 120px; min-width: 0; } #dash-root .sc-field input, #dash-root .sc-field select { min-width: 0; width: 100%; } #dash-root .sc-title { font-size: 26px; } #dash-root .sc-title-note { display: block; font-size: 20px; } #dash-root .sc-kpi { padding: 15px 12px; } #dash-root .sc-value { font-size: 28px; } }
@media (forced-colors: active) { #dash-root .sc-chart svg rect { fill: CanvasText; } #dash-root .sc-chart svg path { stroke: LinkText; } }
